class PersonalityEngine{constructor(){this.personalityTypes={explorer:{name:"Explorer",readingSpeed:{min:180,max:220},readingStyle:"curious",interactionLevel:"high",scrollBehavior:"exploratory",pauseFrequency:"medium"},researcher:{name:"Researcher",readingSpeed:{min:150,max:180},readingStyle:"thorough",interactionLevel:"medium",scrollBehavior:"systematic",pauseFrequency:"high"},casual:{name:"Casual",readingSpeed:{min:200,max:250},readingStyle:"skim",interactionLevel:"low",scrollBehavior:"quick",pauseFrequency:"low"},professional:{name:"Professional",readingSpeed:{min:160,max:200},readingStyle:"focused",interactionLevel:"medium",scrollBehavior:"efficient",pauseFrequency:"medium"}},this.currentPersonality=this.selectRandomPersonality(),this.sessionStartTime=Date.now()}selectRandomPersonality(){const e=Object.keys(this.personalityTypes);return e[Math.floor(Math.random()*e.length)]}determinePersonalization(e){const t=this.analyzeContentTopics(e||""),r=this.getReadingPreferences();return{personality:this.currentPersonality,topics:t,preferences:r,deviceType:this.getDeviceType(),timeOfDay:this.getTimeOfDay()}}determineReadingBehavior(){const e=this.personalityTypes[this.currentPersonality];return{type:this.currentPersonality,readingSpeed:this.getRandomInRange(e.readingSpeed),style:e.readingStyle,interactionLevel:e.interactionLevel,scrollBehavior:e.scrollBehavior,pauseFrequency:e.pauseFrequency,eyeMovement:this.generateEyeMovementPattern(),textSelection:this.shouldSelectText(),reReading:this.shouldReRead()}}calculateReadingTime(e){const t=this.getWordCount(e||""),r=this.personalityTypes[this.currentPersonality];let n=t/this.getRandomInRange(r.readingSpeed);switch(this.currentPersonality){case"researcher":n*=1.5;break;case"casual":n*=.7;break;case"explorer":n*=1.2;break;case"professional":n*=1.1}return Math.max(2,Math.min(5,Math.ceil(n)))}analyzeContentTopics(e){const t=e&&e.text||e||"",r=`${e&&e.title||""} ${t}`.toLowerCase(),n=[];return Object.entries({technology:["tech","software","programming","computer","digital","app","mobile","web","internet"],business:["business","entrepreneur","startup","company","market","finance","money","investment"],health:["health","medical","fitness","wellness","diet","exercise","nutrition","medicine"],lifestyle:["lifestyle","fashion","beauty","travel","food","home","family","life"],education:["education","learning","study","course","tutorial","guide","knowledge","school"]}).forEach(([e,t])=>{const i=t.filter(e=>r.includes(e)).length;i>0&&n.push({topic:e,relevance:i/t.length,keywords:t.filter(e=>r.includes(e))})}),n.sort((e,t)=>t.relevance-e.relevance),n}getReadingPreferences(){return{fontSize:this.getPreferredFontSize(),lineHeight:this.getPreferredLineHeight(),colorScheme:this.getPreferredColorScheme(),focusAreas:this.getFocusAreas()}}getPreferredFontSize(){return this.weightedRandomChoice(["small","medium","large"],[.3,.5,.2])}getPreferredLineHeight(){const e=[1.2,1.4,1.6,1.8];return e[Math.floor(Math.random()*e.length)]}getPreferredColorScheme(){return Math.random()>.5?"light":"dark"}getFocusAreas(){const e=Math.floor(3*Math.random())+2;return this.shuffleArray(["title","introduction","main-content","conclusion","images"]).slice(0,e)}generateEyeMovementPattern(){return{explorer:"zigzag",researcher:"linear",casual:"quick-scan",professional:"focused-linear"}[this.currentPersonality]}shouldSelectText(){return Math.random()<{explorer:.3,researcher:.6,casual:.1,professional:.4}[this.currentPersonality]}shouldReRead(){return Math.random()<{explorer:.2,researcher:.5,casual:.05,professional:.3}[this.currentPersonality]}getDeviceType(){const e=navigator.userAgent;return/Android|iPhone|iPad|iPod|BlackBerry|Windows Phone/i.test(e)?"mobile":"desktop"}getTimeOfDay(){const e=(new Date).getHours();return e>=6&&e<12?"morning":e>=12&&e<17?"afternoon":e>=17&&e<21?"evening":"night"}getWordCount(e){return e&&"string"==typeof e?e.split(/\s+/).filter(e=>e.length>0).length:0}getRandomInRange(e){return Math.random()*(e.max-e.min)+e.min}weightedRandomChoice(e,t){const r=t.reduce((e,t)=>e+t,0);let n=Math.random()*r;for(let r=0;r<e.length;r++)if(n-=t[r],n<=0)return e[r];return e[e.length-1]}shuffleArray(e){const t=[...e];for(let e=t.length-1;e>0;e--){const r=Math.floor(Math.random()*(e+1));[t[e],t[r]]=[t[r],t[e]]}return t}getPersonalityInfo(){return{type:this.currentPersonality,name:this.personalityTypes[this.currentPersonality].name,sessionStartTime:this.sessionStartTime,sessionDuration:Date.now()-this.sessionStartTime}}}